SET DEFINE OFF;
WHENEVER SQLERROR EXIT FAILURE ROLLBACK;
-- Maintenance recovery ONLY before any salary is published.
-- If publication already happened this script aborts; never erase a valid publication lock.
DECLARE n NUMBER; c NUMBER; BEGIN
 SELECT COUNT(*) INTO c FROM USER_TAB_COLUMNS WHERE TABLE_NAME='TB_KYCONG' AND COLUMN_NAME='LUONG_CONGBO_LOCKED';
 IF c=1 THEN EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM TB_KYCONG WHERE LUONG_CONGBO_LOCKED=1' INTO n;
  IF n>0 THEN RAISE_APPLICATION_ERROR(-20046,'Published payroll exists: rollback prohibited.'); END IF;
 END IF;
 SELECT COUNT(*) INTO n FROM TB_BANGLUONG WHERE UPPER(TRIM(TRANG_THAI)) IN ('PUBLISHED','APPROVED','CONG_BO','DA_DUYET','PAID','DA_CHI_TRA');
 IF n>0 THEN RAISE_APPLICATION_ERROR(-20046,'Published payroll exists: rollback prohibited.'); END IF;
 SELECT COUNT(*) INTO n FROM USER_TRIGGERS WHERE TRIGGER_NAME='TRG45_PERIOD_FROZEN'; IF n=1 THEN EXECUTE IMMEDIATE 'DROP TRIGGER TRG45_PERIOD_FROZEN'; END IF;
 SELECT COUNT(*) INTO n FROM USER_TRIGGERS WHERE TRIGGER_NAME='TRG45_PAYROLL_FROZEN'; IF n=1 THEN EXECUTE IMMEDIATE 'DROP TRIGGER TRG45_PAYROLL_FROZEN'; END IF;
